{"path": "/tmp/sv-9ffe237565f24fdea5728394edd2ed49/Components/Pages/Apply.razor", "file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_9ffe237565f24fdea5728394edd2ed49.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!_submitted)
    {
        @* Step 1: Personal Info *@
        @if (_currentStep == 0)
        {
            <div class="form-step">
                <h2>Personal Information</h2>
                <div class="form-group">
                    <label for="fullName">Full Name *</label>
                    <input id="fullName" type="text" @bind="_fullName" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="email">Email *</label>
                    <input id="email" type="email" @bind="_email" class="form-control" />
                    @if (!string.IsNullOrEmpty(_emailError))
                    {
                        <span class="field-error">@_emailError</span>
                    }
                </div>
                <div class="form-group">
                    <label for="phone">Phone *</label>
                    <input id="phone" type="tel" @bind="_phone" class="form-control" />
                </div>
                <div class="form-group">
                    <label for="address">Address *</label>
                    <input id="address" type="text" @bind="_address" class="form-control" />
                </div>
                @if (!string.IsNullOrEmpty(_validationError))
                {
                    <div class="validation-error">@_validationError</div>
                }
                <div class="form-buttons">
                    <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidating">
                        @(_isValidating ? "Validating..." : "Next")
                    </button>
                </div>
            </div>
        }

        @* Step 2: Work History *@
        @if (_currentStep == 1)
        {
            <div class="form-step">
                <h2>Work History</h2>
                @for (int i = 0; i < _workEntries.Count; i++)
                {
                    var index = i;
                    <div class="work-entry-card">
                        <div class="work-entry-header">
                            <h3>Position @(index + 1)</h3>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                            }
                        </div>
                        <div class="form-group">
                            <label>Company Name *</label>
                            <input type="text" @bind="_workEntries[index].Company" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label>Job Title *</label>
                            <input type="text" @bind="_workEntries[index].Title" class="form-control" />
                        </div>
                        <div class="form-row">
                            <div class="form-group">
                                <label>Start Date *</label>
                                <input type="date" @bind="_workEntries[index].StartDate" class="form-control" />
                            </div>
                            <div class="form-group">
                                @if (!_workEntries[index].IsCurrent)
                                {
                                    <label>End Date</label>
                                    <input type="date" @bind="_workEntries[index].EndDate" class="form-control" />
                                }
                            </div>
                        </div>
                        <div class="form-group checkbox-group">
                            <input type="checkbox" id="current-@index" @bind="_workEntries[index].IsCurrent" />
                            <label for="current-@index">I currently work here</label>
                        </div>
                        <div class="form-group">
                            <label>Description</label>
                            <textarea @bind="_workEntries[index].Description" class="form-control" rows="3"></textarea>
                        </div>
                    </div>
                }
                <button class="btn btn-secondary" @onclick="AddWorkEntry">+ Add Another Position</button>
                @if (!string.IsNullOrEmpty(_validationError))
                {
                    <div class="validation-error">@_validationError</div>
                }
                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        @* Step 3: References *@
        @if (_currentStep == 2)
        {
            <div class="form-step">
                <h2>References</h2>
                @for (int i = 0; i < _references.Count; i++)
                {
                    var index = i;
                    <div class="reference-card">
                        <div class="work-entry-header">
                            <h3>Reference @(index + 1)</h3>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                            }
                        </div>
                        <div class="form-group">
                            <label>Name *</label>
                            <input type="text" @bind="_references[index].Name" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label>Relationship *</label>
                            <input type="text" @bind="_references[index].Relationship" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label>Email *</label>
                            <input type="email" @bind="_references[index].Email" class="form-control" />
                        </div>
                        <div class="form-group">
                            <label>Phone *</label>
                            <input type="tel" @bind="_references[index].Phone" class="form-control" />
                        </div>
                    </div>
                }
                @if (_references.Count < 3)
                {
                    <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
                }
                @if (!string.IsNullOrEmpty(_validationError))
                {
                    <div class="validation-error">@_validationError</div>
                }
                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        @* Step 4: Cover Letter *@
        @if (_currentStep == 3)
        {
            <div class="form-step">
                <h2>Cover Letter</h2>
                <div class="form-group">
                    <textarea @bind="_coverLetter" @bind:event="oninput" class="form-control cover-letter-textarea" rows="12" maxlength="2000"></textarea>
                    <div class="character-count">@_coverLetter.Length / 2000 characters</div>
                </div>
                @if (!string.IsNullOrEmpty(_validationError))
                {
                    <div class="validation-error">@_validationError</div>
                }
                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary" @onclick="NextStep">Next</button>
                </div>
            </div>
        }

        @* Step 5: Review & Submit *@
        @if (_currentStep == 4)
        {
            <div class="form-step">
                <h2>Review &amp; Submit</h2>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Personal Information</h3>
                        <a href="#" @onclick="() => GoToStep(0)" @onclick:preventDefault>Edit</a>
                    </div>
                    <dl class="review-list">
                        <dt>Full Name</dt><dd>@_fullName</dd>
                        <dt>Email</dt><dd>@_email</dd>
                        <dt>Phone</dt><dd>@_phone</dd>
                        <dt>Address</dt><dd>@_address</dd>
                    </dl>
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Work History</h3>
                        <a href="#" @onclick="() => GoToStep(1)" @onclick:preventDefault>Edit</a>
                    </div>
                    @foreach (var entry in _workEntries)
                    {
                        <div class="review-work-entry">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                            <div>@entry.StartDate.ToString("MMM yyyy") &mdash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</div>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p>@entry.Description</p>
                            }
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>References</h3>
                        <a href="#" @onclick="() => GoToStep(2)" @onclick:preventDefault>Edit</a>
                    </div>
                    @foreach (var reference in _references)
                    {
                        <div class="review-reference">
                            <strong>@reference.Name</strong> (@reference.Relationship)
                            <div>@reference.Email &bull; @reference.Phone</div>
                        </div>
                    }
                </div>

                <div class="review-section">
                    <div class="review-header">
                        <h3>Cover Letter</h3>
                        <a href="#" @onclick="() => GoToStep(3)" @onclick:preventDefault>Edit</a>
                    </div>
                    <p class="review-cover-letter">@_coverLetter</p>
                </div>

                @if (!string.IsNullOrEmpty(_submissionError))
                {
                    <div class="validation-error">@_submissionError</div>
                }
                <div class="form-buttons">
                    <button class="btn btn-outline" @onclick="PreviousStep">Back</button>
                    <button class="btn btn-primary btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
                        @(_isSubmitting ? "Submitting..." : "Submit Application")
                    </button>
                </div>
            </div>
        }
    }
    else
    {
        @* Confirmation *@
        <div class="confirmation">
            <div class="confirmation-icon">&#10003;</div>
            <h2>Application Submitted!</h2>
            <p>Your application has been successfully submitted.</p>
            <p class="application-id">Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep;
    private int _highestCompletedStep = -1;

    // Step 1 fields
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;
    private string _emailError = string.Empty;
    private bool _isValidating;

    // Step 2 fields
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string _coverLetter = string.Empty;

    // General state
    private string _validationError = string.Empty;
    private string _submissionError = string.Empty;
    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;

    private string GetStepClass(int step)
    {
        if (step == _currentStep) return "active";
        if (IsStepCompleted(step)) return "completed";
        return "dimmed";
    }

    private bool IsStepCompleted(int step) => step <= _highestCompletedStep;

    private void GoToStep(int step)
    {
        if (IsStepCompleted(step))
        {
            _currentStep = step;
            _validationError = string.Empty;
        }
    }

    private async Task NextStep()
    {
        _validationError = string.Empty;
        _emailError = string.Empty;

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 0)
        {
            _isValidating = true;
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isValidating = false;
            if (!emailValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
        }

        if (_currentStep > _highestCompletedStep)
            _highestCompletedStep = _currentStep;

        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
        {
            _validationError = string.Empty;
            _currentStep--;
        }
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
                    string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
                {
                    _validationError = "All fields are required.";
                    return false;
                }
                break;
            case 1:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                        entry.StartDate == default)
                    {
                        _validationError = "Company, job title, and start date are required for each position.";
                        return false;
                    }
                }
                break;
            case 2:
                foreach (var reference in _references)
                {
                    if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                        string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
                    {
                        _validationError = "All fields are required for each reference.";
                        return false;
                    }
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                {
                    _validationError = "Please write a cover letter.";
                    return false;
                }
                break;
        }
        return true;
    }

    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
            _workEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _submissionError = string.Empty;

        try
        {
            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
            var workHistory = new WorkHistory(_workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? string.Empty)
            ).ToList());
            var references = _references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList();

            var application = new JobApplication(personal, workHistory, references, _coverLetter);
            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submissionError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string? Description { get; set; }
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}
"}

